(()=>{const p=new URLSearchParams(location.search),entryId=p.get('focus_entry'),memoryId=p.get('focus_memory'),memoryTab=p.get('memory_tab');const focus=card=>{if(!card)return;card.classList.add('entry-focused');if(!card.querySelector('.focus-label')){const label=document.createElement('div');label.className='focus-label';label.textContent='Открытая запись';card.prepend(label)}card.scrollIntoView({behavior:'smooth',block:'center'})};const oldKnowledge=renderKnowledge;renderKnowledge=items=>{oldKnowledge(items);for(const [index,item] of items.entries()){const card=document.querySelectorAll('#entries>.entry')[index];if(card)card.id=`knowledge-${item.id}`}if(entryId)focus(document.getElementById(`knowledge-${entryId}`)||document.querySelector(`[data-testid="knowledge-entry-${entryId}"]`))};const oldMemory=renderMemory;renderMemory=items=>{oldMemory(items);for(const [index,item] of items.entries()){const card=document.querySelectorAll('#memory-items>.entry')[index];if(!card)continue;const itemType=memoryView==='facts'?'fact':memoryView==='decisions'?'decision':'document';card.id=`memory-${itemType}-${item.id}`;card.dataset.testid=`memory-${itemType}-${item.id}`}if(memoryId){const itemType=memoryView==='facts'?'fact':memoryView==='decisions'?'decision':'document';focus(document.getElementById(`memory-${itemType}-${memoryId}`))}};const tabs=document.querySelector('#memory .tabs');if(tabs&&!tabs.querySelector('[data-memory="documents"]')){const docs=document.createElement('button');docs.dataset.memory='documents';docs.textContent='Документы';docs.onclick=()=>{memoryView='documents';document.querySelectorAll('[data-memory]').forEach(tab=>tab.classList.toggle('active',tab===docs));loadMemory()};tabs.append(docs)}if(view==='memory'&&memoryTab&&['facts','decisions','documents'].includes(memoryTab)){memoryView=memoryTab;setTimeout(loadMemory,0)}})();

const focusParams=new URLSearchParams(location.search),focusView=focusParams.get('view');if(['artem','idea'].includes(focusView)){view=focusView;setTimeout(()=>api(`/api/entries?kind=${focusView}&query=`).then(renderKnowledge).catch(error=>show(error.message,true)),50)}if(focusView==='memory'){memoryView=focusParams.get('memory_tab')||'context';if(memoryView!=='context')setTimeout(()=>api(`/api/memory/${memoryView}?query=`).then(renderMemory).catch(error=>show(error.message,true)),50)}

(()=>{
const normalLoadMemory=loadMemory,make=(tag,text,testid)=>{const element=document.createElement(tag);if(text!==undefined)element.textContent=text;if(testid)element.dataset.testid=testid;return element};
function feedback(holder,text,error=false){holder.className=error?'error':'result';holder.textContent=text}
async function candidateDetail(item,card,button){button.disabled=true;try{const detail=await api(`/api/memory/candidates/${encodeURIComponent(item.id)}`),box=make('section');box.dataset.testid=`memory-candidate-detail-${item.id}`;box.append(make('div',`Статус: ${detail.status}`,'memory-candidate-status'),make('div',`Semantic key: ${detail.semantic_key}`,'memory-candidate-key'),make('p',detail.content,'memory-candidate-content'),make('div',`Источник: ${detail.source_title} · ${detail.source_type} · ${detail.source_author}`,'memory-candidate-source'));if(detail.task_id)box.append(make('div',`Связанная задача: ${detail.task_title} · ${detail.task_status}`,'memory-candidate-task'));if(detail.conflicts.some(x=>x.status==='open')){const warning=make('p','Есть открытый конфликт. Подтверждение не изменит действующую память до отдельного разрешения.','memory-candidate-warning');warning.className='memory-warning';box.append(warning)}const form=make('form');form.className='memory-review-form';form.dataset.testid=`memory-candidate-form-${item.id}`;const label=make('label','Комментарий к подтверждению (необязательно) или причина отклонения');const note=make('textarea',undefined,`memory-candidate-note-${item.id}`);label.append(note);const actions=make('div');actions.className='actions';const approve=make('button','Подтвердить',`memory-candidate-approve-${item.id}`),reject=make('button','Отклонить',`memory-candidate-reject-${item.id}`),result=make('div',undefined,`memory-candidate-feedback-${item.id}`);reject.className='cancel';actions.append(approve,reject);form.append(label,actions,result);form.onsubmit=event=>event.preventDefault();approve.onclick=async()=>{approve.disabled=reject.disabled=true;try{const reviewed=await api(`/api/memory/candidates/${encodeURIComponent(item.id)}/approve`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({comment:note.value})});feedback(result,reviewed.conflicts.some(x=>x.status==='open')?'Кандидат подтверждён. Перейдите в «Конфликты».':'Кандидат подтверждён.');await loadMemory()}catch(error){feedback(result,error.message,true);approve.disabled=reject.disabled=false}};reject.onclick=async()=>{if(!note.value.trim()){feedback(result,'Укажите причину отклонения.',true);note.focus();return}approve.disabled=reject.disabled=true;try{await api(`/api/memory/candidates/${encodeURIComponent(item.id)}/reject`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason:note.value})});feedback(result,'Кандидат отклонён.');await loadMemory()}catch(error){feedback(result,error.message,true);approve.disabled=reject.disabled=false}};box.append(form);button.replaceWith(box)}catch(error){button.disabled=false;const result=make('div',error.message);result.className='error';button.after(result)}}
function renderCandidates(items){memoryItems.replaceChildren();if(!items.length){memoryItems.append(make('p','Кандидатов на проверку нет.','memory-candidates-empty'));return}for(const item of items){const card=make('article');card.className='entry';card.dataset.testid=`memory-candidate-${item.id}`;card.append(make('strong',item.title),make('div',`${item.type} · ${item.created_at}`,'meta'),make('div',item.semantic_key,'meta'),make('p',item.content.length>240?`${item.content.slice(0,239)}…`:item.content));if(item.task_title)card.append(make('div',`Задача: ${item.task_title}`,'meta'));if(item.conflict_count){const warning=make('p','Есть конфликт','memory-candidate-warning');warning.className='memory-warning';card.append(warning)}const details=make('button','Подробнее',`memory-candidate-details-${item.id}`);details.onclick=()=>candidateDetail(item,card,details);card.append(details);memoryItems.append(card)}}
function renderConflicts(items){memoryItems.replaceChildren();if(!items.length){memoryItems.append(make('p','Открытых конфликтов нет.','memory-conflicts-empty'));return}for(const item of items){const card=make('article');card.className='entry';card.dataset.testid=`memory-conflict-${item.id}`;card.append(make('strong',item.title),make('div',item.semantic_key,'meta'),make('div',`Источник: ${item.source_title}${item.task_title?` · задача: ${item.task_title}`:''}`,'meta'));const compare=make('div');compare.className='memory-comparison';const current=make('section'),candidate=make('section');current.append(make('h3','Текущая память'),make('strong',item.existing_title),make('p',item.existing_content,'memory-existing-content'));candidate.append(make('h3','Кандидат'),make('strong',item.candidate_title),make('p',item.candidate_content,'memory-conflicting-content'));compare.append(current,candidate);const form=make('form');form.className='memory-review-form';const label=make('label','Причина решения конфликта (обязательно)'),reason=make('textarea',undefined,`memory-conflict-reason-${item.id}`);label.append(reason);const actions=make('div');actions.className='actions';const accept=make('button','Принять кандидат',`memory-conflict-accept-${item.id}`),keep=make('button','Оставить текущее',`memory-conflict-keep-${item.id}`),result=make('div',undefined,`memory-conflict-feedback-${item.id}`);keep.className='cancel';actions.append(accept,keep);form.append(label,actions,result);form.onsubmit=event=>event.preventDefault();const resolve=async(outcome)=>{if(!reason.value.trim()){feedback(result,'Укажите причину решения конфликта.',true);reason.focus();return}accept.disabled=keep.disabled=true;try{await api(`/api/memory/conflicts/${encodeURIComponent(item.id)}/resolve`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({outcome,reason:reason.value})});feedback(result,'Конфликт разрешён.');await loadMemory()}catch(error){feedback(result,error.message,true);accept.disabled=keep.disabled=false}};accept.onclick=()=>resolve('candidate');keep.onclick=()=>resolve('existing');card.append(compare,form);memoryItems.append(card)}}
loadMemory=async()=>{if(!['candidates','conflicts'].includes(memoryView))return normalLoadMemory();try{memoryContext.classList.add('hidden');memorySearchRow.classList.toggle('hidden',memoryView==='conflicts');const query=memoryView==='candidates'?`?query=${encodeURIComponent(memorySearch.value)}`:'';const items=await api(`/api/memory/${memoryView}${query}`);if(memoryView==='candidates')renderCandidates(items);else renderConflicts(items)}catch(error){show(error.message,true)}};
if(view==='memory'&&new URLSearchParams(location.search).get('memory_tab')==='candidates'){memoryView='candidates';setTimeout(loadMemory,0)}
})();

document.addEventListener('click',event=>{const button=event.target.closest('[data-testid="overview-new-task"]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();document.querySelector('[data-view="tasks"]').click();window.metricHitOpenTaskModal?.()},true);

(()=>{const overview=document.querySelector('#overview'),tab=name=>document.querySelector(`[data-view="${name}"]`),openTask=id=>`/?view=tasks&focus_task=${encodeURIComponent(id)}#task-${id}`;const node=(tag,text,cls)=>{const value=document.createElement(tag);if(text!==undefined)value.textContent=text;if(cls)value.className=cls;return value};function section(title,testid,priority=false){const box=node('section',undefined,'overview-card');if(priority)box.classList.add('overview-priority');box.dataset.testid=testid;box.append(node('h2',title));return box}function empty(box,text,testid){const value=node('p',text,'overview-empty');if(testid)value.dataset.testid=testid;box.append(value)}function taskRow(task){const row=node('div',undefined,'overview-task');row.dataset.testid=`overview-task-${task.id}`;const label=node('span',`${task.display_title}${task.project_name?` · ${task.project_name}`:''} · ${task.priority}${task.due_date?` · ${task.due_date}`:''}`),open=node('a','Открыть');open.href=openTask(task.id);open.dataset.testid=`overview-open-${task.id}`;row.append(label,open);return row}function today(data){const box=section('Сегодня','overview-today-priority',true);if(data.error){empty(box,data.error);return box}const items=[...(data.overdue_items||[]),...(data.today_items||[])];if(!items.length)empty(box,'На сегодня срочных задач нет.','overview-empty-today');else items.forEach(item=>box.append(taskRow(item)));return box}function pending(data){const box=section('Ожидают решения','overview-pending-decisions');if(data.pending===undefined){empty(box,'Состояние памяти временно недоступно.');return box}box.append(node('p',`Кандидаты: ${data.pending} · конфликты: ${data.conflicts}`));const open=node('a','Открыть решения');open.href='/?view=memory&memory_tab=candidates';open.dataset.testid='overview-open-pending-decisions';box.append(open);return box}function nearest(data){const box=section('Ближайшие задачи','overview-nearest-tasks');if(data.error){empty(box,data.error);return box}if(!data.items.length)empty(box,'Открытых задач нет.','overview-empty-tasks');else data.items.forEach(item=>box.append(taskRow(item)));return box}function activity(data){const box=section('Недавняя активность','overview-recent-activity');if(data.error){empty(box,'Активность временно недоступна.');return box}if(!data.items.length){empty(box,'Событий пока нет.');return box}for(const item of data.items.slice(0,3)){const row=node('div',undefined,'overview-task');row.dataset.testid=`overview-activity-${item.id}`;row.append(node('span',`${item.label} · ${item.title}`),node('span',item.date,'meta'));box.append(row)}const open=node('a','Вся активность');open.href='/?view=activity';box.append(open);return box}function quick(){const box=section('Быстрые действия','overview-quick-actions');for(const [label,name,testid] of [['Новая задача','tasks','overview-new-task'],['Добавить рекомендацию','artem','overview-add-artem'],['Добавить идею','idea','overview-add-idea']]){const button=node('button',label);button.dataset.testid=testid;button.onclick=()=>{tab(name).click();if(name==='tasks')setTimeout(()=>document.querySelector('#new-task')?.click(),0)};box.append(button)}return box}async function render(){if(view!=='overview')return;const [dashboard,events]=await Promise.allSettled([api('/api/dashboard'),api('/api/activity?period=7&item_type=all&action=all&offset=0')]);if(view!=='overview')return;overview.replaceChildren();if(dashboard.status!=='fulfilled'){empty(overview,'Обзор временно недоступен.');return}const grid=node('div',undefined,'overview-grid'),data=dashboard.value,activityData=events.status==='fulfilled'?events.value:{error:true};grid.append(today(data.tasks),pending(data.memory),nearest(data.tasks),activity(activityData),quick());overview.append(grid)}for(const button of document.querySelectorAll('[data-view]'))button.addEventListener('click',()=>{if(button.dataset.view==='overview')setTimeout(render,0)});setTimeout(render,20)})();

(()=>{const DEFAULT='00000000-0000-4000-a000-000000000102';let scopes=[];const originalApi=api;api=async(path,options={})=>{if(options.method==='POST'&&options.body&&['/api/entries','/api/tasks','/api/projects'].some(prefix=>path===prefix||path.startsWith('/api/tasks/'))){try{const body=JSON.parse(options.body);if(path==='/api/entries'){const form=document.querySelector('#add');body.project_id=form?.elements.project_id?.value||body.project_id||DEFAULT;body.subproject_id=form?.elements.subproject_id?.value||null}else if(path==='/api/tasks'||path.startsWith('/api/tasks/')){const form=document.querySelector('[data-testid^="task-"][data-testid$="form"], [data-testid="task-form"]');body.project_id=form?.elements.project_id?.value||body.project_id||DEFAULT;body.subproject_id=form?.elements.subproject_id?.value||null}else if(path==='/api/projects'){body.parent_project_id=document.querySelector('[data-testid="project-parent"]')?.value||null}options={...options,body:JSON.stringify(body)}}catch{}}return originalApi(path,options)};
function addContext(){const header=document.querySelector('.panel-header');if(!header||header.querySelector('[data-testid="active-scope"]'))return;const context=document.createElement('div');context.className='scope-context';context.dataset.testid='active-scope';context.innerHTML='Текущий контекст: <strong>MetricHit</strong>';header.querySelector('nav')?.before(context)}
function ensurePair(form,prefix){if(!form||form.querySelector(`[data-testid="${prefix}-subproject"]`))return;let project=form.elements.project_id;if(!project){const label=document.createElement('label');label.textContent='Проект';project=document.createElement('select');project.name='project_id';project.dataset.testid=`${prefix}-project`;label.append(project);form.querySelector('button')?.before(label)}project.required=true;const label=document.createElement('label');label.textContent='Подпроект';const child=document.createElement('select');child.name='subproject_id';child.dataset.testid=`${prefix}-subproject`;label.append(child);project.closest('label')?.after(label);const fillChildren=()=>{const current=child.value;child.replaceChildren(new Option('Без подпроекта',''));for(const item of scopes)if(item.status==='active'&&item.scope_type==='subproject'&&item.parent_project_id===project.value)child.append(new Option(item.name,item.id));if([...child.options].some(x=>x.value===current))child.value=current};project.onchange=fillChildren;project.replaceChildren();for(const item of scopes)if(item.status==='active'&&item.scope_type==='independent')project.append(new Option(item.name,item.id));if(!project.value)project.value=DEFAULT;fillChildren()}
async function enhance(){scopes=await originalApi('/api/projects');addContext();ensurePair(document.querySelector('#add'),'knowledge');ensurePair(document.querySelector('[data-testid="task-form"], [data-testid^="task-edit-form-"]'),'task');const modal=document.querySelector('[data-testid="project-modal"] form');if(modal&&!modal.querySelector('[data-testid="project-parent"]')){const label=document.createElement('label');label.textContent='Родительский проект (пусто — самостоятельный проект)';const select=document.createElement('select');select.dataset.testid='project-parent';select.append(new Option('Самостоятельный проект',''));for(const item of scopes)if(item.status==='active'&&item.scope_type==='independent')select.append(new Option(item.name,item.id));label.append(select);modal.querySelector('[data-testid="project-description"]')?.after(label)}const byId=Object.fromEntries(scopes.map(item=>[item.id,item]));for(const card of document.querySelectorAll('[data-testid^="project-card-"]')){if(card.querySelector('[data-testid="project-scope-kind"]'))continue;const item=byId[card.dataset.testid.slice('project-card-'.length)];if(!item||item.id==='unassigned')continue;const kind=document.createElement('div');kind.className='meta';kind.dataset.testid='project-scope-kind';kind.textContent=item.scope_type==='subproject'?`Подпроект · ${byId[item.parent_project_id]?.name||'неизвестный родитель'}`:'Самостоятельный проект';card.querySelector('strong')?.after(kind)}}
window.metricHitRefreshProjects=async(form,current)=>{scopes=await originalApi('/api/projects');ensurePair(form,'task');const project=form.elements.project_id;project.replaceChildren();for(const item of scopes)if(item.status==='active'&&item.scope_type==='independent')project.append(new Option(item.name,item.id));project.value=current&&[...project.options].some(x=>x.value===current)?current:DEFAULT;project.onchange?.()};new MutationObserver(()=>enhance().catch(()=>{})).observe(document.body,{childList:true,subtree:true});enhance().catch(error=>show(error.message,true))})();
